{
  "kind": "mode",
  "schema": {
    "$defs": {
      "Circle": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "circle",
            "default": "circle",
            "title": "Kind",
            "type": "string"
          },
          "center_nm": {
            "default": [
              0.0,
              0.0
            ],
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "radius_nm": {
            "exclusiveMinimum": 0,
            "title": "Radius Nm",
            "type": "number"
          }
        },
        "required": [
          "radius_nm"
        ],
        "title": "Circle",
        "type": "object"
      },
      "ConstantIndex": {
        "additionalProperties": false,
        "description": "Wavelength-independent complex refractive index n + ik.",
        "properties": {
          "kind": {
            "const": "constant_index",
            "default": "constant_index",
            "title": "Kind",
            "type": "string"
          },
          "n_real": {
            "description": "Real part of the refractive index.",
            "title": "N Real",
            "type": "number"
          },
          "n_imag": {
            "default": 0.0,
            "description": "Extinction coefficient k (>= 0 for loss).",
            "minimum": 0,
            "title": "N Imag",
            "type": "number"
          }
        },
        "required": [
          "n_real"
        ],
        "title": "ConstantIndex",
        "type": "object"
      },
      "ConstantPermittivity": {
        "additionalProperties": false,
        "description": "Wavelength-independent complex relative permittivity.",
        "properties": {
          "kind": {
            "const": "constant_permittivity",
            "default": "constant_permittivity",
            "title": "Kind",
            "type": "string"
          },
          "eps_real": {
            "title": "Eps Real",
            "type": "number"
          },
          "eps_imag": {
            "default": 0.0,
            "minimum": 0,
            "title": "Eps Imag",
            "type": "number"
          }
        },
        "required": [
          "eps_real"
        ],
        "title": "ConstantPermittivity",
        "type": "object"
      },
      "Drude": {
        "additionalProperties": false,
        "description": "eps(w) = eps_inf - wp^2 / (w^2 + i*gamma*w), energies in eV.",
        "properties": {
          "kind": {
            "const": "drude",
            "default": "drude",
            "title": "Kind",
            "type": "string"
          },
          "eps_inf": {
            "default": 1.0,
            "title": "Eps Inf",
            "type": "number"
          },
          "wp_ev": {
            "description": "Plasma frequency in eV.",
            "exclusiveMinimum": 0,
            "title": "Wp Ev",
            "type": "number"
          },
          "gamma_ev": {
            "description": "Damping rate in eV.",
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          }
        },
        "required": [
          "wp_ev",
          "gamma_ev"
        ],
        "title": "Drude",
        "type": "object"
      },
      "DrudeLorentz": {
        "additionalProperties": false,
        "description": "eps(w) = eps_inf - wp^2/(w^2 + i g w) + sum_j d_j w0_j^2 / (w0_j^2 - w^2 - i G_j w).\n\nThe form FDTD needs for auxiliary-differential-equation dispersion.\nFit one to measured data with :func:`lightsmith.materials_fit.fit_drude_lorentz`.",
        "properties": {
          "kind": {
            "const": "drude_lorentz",
            "default": "drude_lorentz",
            "title": "Kind",
            "type": "string"
          },
          "eps_inf": {
            "default": 1.0,
            "title": "Eps Inf",
            "type": "number"
          },
          "wp_ev": {
            "default": 0.0,
            "minimum": 0,
            "title": "Wp Ev",
            "type": "number"
          },
          "gamma_ev": {
            "default": 0.0,
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          },
          "poles": {
            "items": {
              "$ref": "#/$defs/LorentzPole"
            },
            "title": "Poles",
            "type": "array"
          }
        },
        "title": "DrudeLorentz",
        "type": "object"
      },
      "Ellipse": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "ellipse",
            "default": "ellipse",
            "title": "Kind",
            "type": "string"
          },
          "center_nm": {
            "default": [
              0.0,
              0.0
            ],
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "semi_axes_nm": {
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Semi Axes Nm",
            "type": "array"
          },
          "angle_deg": {
            "default": 0.0,
            "title": "Angle Deg",
            "type": "number"
          }
        },
        "required": [
          "semi_axes_nm"
        ],
        "title": "Ellipse",
        "type": "object"
      },
      "LibraryMaterial": {
        "additionalProperties": false,
        "description": "Measured n, k bundled with lightsmith, e.g. ``{\"kind\": \"library\", \"name\": \"Au\",\n\"dataset\": \"Johnson-Christy\"}``. Linear interpolation in n and k, no extrapolation.\n\nNames and datasets accept aliases (\"gold\", \"JC\") and are stored in canonical form;\nan omitted dataset is filled with the material's default so the spec stays\nreproducible. See :func:`list_materials`.",
        "properties": {
          "kind": {
            "const": "library",
            "default": "library",
            "title": "Kind",
            "type": "string"
          },
          "name": {
            "description": "Material, e.g. 'Au', 'Ag', 'Al', 'Cu', 'Si', 'TiO2', 'SiO2', 'H2O'.",
            "title": "Name",
            "type": "string"
          },
          "dataset": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Dataset, e.g. 'Johnson-Christy'; omitted = material default.",
            "title": "Dataset"
          }
        },
        "required": [
          "name"
        ],
        "title": "LibraryMaterial",
        "type": "object"
      },
      "LorentzPole": {
        "additionalProperties": false,
        "properties": {
          "delta_eps": {
            "description": "Oscillator strength (permittivity step).",
            "title": "Delta Eps",
            "type": "number"
          },
          "omega0_ev": {
            "description": "Resonance energy in eV.",
            "exclusiveMinimum": 0,
            "title": "Omega0 Ev",
            "type": "number"
          },
          "gamma_ev": {
            "description": "Damping in eV.",
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          }
        },
        "required": [
          "delta_eps",
          "omega0_ev",
          "gamma_ev"
        ],
        "title": "LorentzPole",
        "type": "object"
      },
      "Polygon": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "polygon",
            "default": "polygon",
            "title": "Kind",
            "type": "string"
          },
          "vertices_nm": {
            "items": {
              "maxItems": 2,
              "minItems": 2,
              "prefixItems": [
                {
                  "type": "number"
                },
                {
                  "type": "number"
                }
              ],
              "type": "array"
            },
            "minItems": 3,
            "title": "Vertices Nm",
            "type": "array"
          }
        },
        "required": [
          "vertices_nm"
        ],
        "title": "Polygon",
        "type": "object"
      },
      "Rectangle": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "rectangle",
            "default": "rectangle",
            "title": "Kind",
            "type": "string"
          },
          "center_nm": {
            "default": [
              0.0,
              0.0
            ],
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "size_nm": {
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Size Nm",
            "type": "array"
          }
        },
        "required": [
          "size_nm"
        ],
        "title": "Rectangle",
        "type": "object"
      },
      "Structure2D": {
        "additionalProperties": false,
        "properties": {
          "name": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Name"
          },
          "profile": {
            "discriminator": {
              "mapping": {
                "circle": "#/$defs/Circle",
                "ellipse": "#/$defs/Ellipse",
                "polygon": "#/$defs/Polygon",
                "rectangle": "#/$defs/Rectangle"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/Rectangle"
              },
              {
                "$ref": "#/$defs/Circle"
              },
              {
                "$ref": "#/$defs/Ellipse"
              },
              {
                "$ref": "#/$defs/Polygon"
              }
            ],
            "title": "Profile"
          },
          "material": {
            "discriminator": {
              "mapping": {
                "constant_index": "#/$defs/ConstantIndex",
                "constant_permittivity": "#/$defs/ConstantPermittivity",
                "drude": "#/$defs/Drude",
                "drude_lorentz": "#/$defs/DrudeLorentz",
                "library": "#/$defs/LibraryMaterial",
                "tabulated": "#/$defs/Tabulated"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/ConstantIndex"
              },
              {
                "$ref": "#/$defs/ConstantPermittivity"
              },
              {
                "$ref": "#/$defs/Drude"
              },
              {
                "$ref": "#/$defs/DrudeLorentz"
              },
              {
                "$ref": "#/$defs/Tabulated"
              },
              {
                "$ref": "#/$defs/LibraryMaterial"
              }
            ],
            "title": "Material"
          }
        },
        "required": [
          "profile",
          "material"
        ],
        "title": "Structure2D",
        "type": "object"
      },
      "Tabulated": {
        "additionalProperties": false,
        "description": "Tabulated n, k data, linearly interpolated (no extrapolation).",
        "properties": {
          "kind": {
            "const": "tabulated",
            "default": "tabulated",
            "title": "Kind",
            "type": "string"
          },
          "wavelength_nm": {
            "items": {
              "type": "number"
            },
            "title": "Wavelength Nm",
            "type": "array"
          },
          "n_real": {
            "items": {
              "type": "number"
            },
            "title": "N Real",
            "type": "array"
          },
          "n_imag": {
            "items": {
              "type": "number"
            },
            "title": "N Imag",
            "type": "array"
          },
          "source": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Citation / provenance of the data.",
            "title": "Source"
          }
        },
        "required": [
          "wavelength_nm",
          "n_real",
          "n_imag"
        ],
        "title": "Tabulated",
        "type": "object"
