      "WavelengthRange": {
        "additionalProperties": false,
        "properties": {
          "start_nm": {
            "exclusiveMinimum": 0,
            "title": "Start Nm",
            "type": "number"
          },
          "stop_nm": {
            "exclusiveMinimum": 0,
            "title": "Stop Nm",
            "type": "number"
          },
          "num": {
            "minimum": 1,
            "title": "Num",
            "type": "integer"
          }
        },
        "required": [
          "start_nm",
          "stop_nm",
          "num"
        ],
        "title": "WavelengthRange",
        "type": "object"
      }
    },
    "additionalProperties": false,
    "description": "Eigenmodes of a waveguide cross-section (xy plane), propagation along +z.",
    "properties": {
      "kind": {
        "const": "mode",
        "default": "mode",
        "title": "Kind",
        "type": "string"
      },
      "structures": {
        "items": {
          "$ref": "#/$defs/Structure2D"
        },
        "minItems": 1,
        "title": "Structures",
        "type": "array"
      },
      "background": {
        "discriminator": {
          "mapping": {
            "constant_index": "#/$defs/ConstantIndex",
            "constant_permittivity": "#/$defs/ConstantPermittivity",
            "drude": "#/$defs/Drude",
            "drude_lorentz": "#/$defs/DrudeLorentz",
            "library": "#/$defs/LibraryMaterial",
            "tabulated": "#/$defs/Tabulated"
          },
          "propertyName": "kind"
        },
        "oneOf": [
          {
            "$ref": "#/$defs/ConstantIndex"
          },
          {
            "$ref": "#/$defs/ConstantPermittivity"
          },
          {
            "$ref": "#/$defs/Drude"
          },
          {
            "$ref": "#/$defs/DrudeLorentz"
          },
          {
            "$ref": "#/$defs/Tabulated"
          },
          {
            "$ref": "#/$defs/LibraryMaterial"
          }
        ],
        "title": "Background"
      },
      "window_center_nm": {
        "default": [
          0.0,
          0.0
        ],
        "maxItems": 2,
        "minItems": 2,
        "prefixItems": [
          {
            "type": "number"
          },
          {
            "type": "number"
          }
        ],
        "title": "Window Center Nm",
        "type": "array"
      },
      "window_size_nm": {
        "maxItems": 2,
        "minItems": 2,
        "prefixItems": [
          {
            "type": "number"
          },
          {
            "type": "number"
          }
        ],
        "title": "Window Size Nm",
        "type": "array"
      },
      "wavelengths": {
        "anyOf": [
          {
            "items": {
              "type": "number"
            },
            "type": "array"
          },
          {
            "$ref": "#/$defs/WavelengthRange"
          }
        ],
        "title": "Wavelengths"
      },
      "num_modes": {
        "default": 2,
        "minimum": 1,
        "title": "Num Modes",
        "type": "integer"
      },
      "target_neff": {
        "anyOf": [
          {
            "type": "number"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "description": "Search near this effective index (default: highest index).",
        "title": "Target Neff"
      },
      "bend_radius_nm": {
        "anyOf": [
          {
            "type": "number"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "description": "Bend about the y axis; None = straight.",
        "title": "Bend Radius Nm"
      },
      "include_fields": {
        "default": false,
        "title": "Include Fields",
        "type": "boolean"
      },
      "options": {
        "additionalProperties": {
          "additionalProperties": true,
          "type": "object"
        },
        "title": "Options",
        "type": "object"
      }
    },
    "required": [
      "structures",
      "background",
      "window_size_nm",
      "wavelengths"
    ],
    "title": "ModeProblem",
    "type": "object"
  },
  "conventions": "Lightsmith conventions (fixed; changing them needs a schema version bump):\n- Lengths in nm. Wavelengths are vacuum wavelengths in nm.\n- Time dependence exp(-i omega t): absorbing materials have Im(eps) > 0 and Im(n) > 0.\n- Cross sections in nm^2; efficiencies Q = C / (pi r_eq^2), r_eq = volume-equivalent radius of all particles.\n- layer_stack / periodic: layers listed from the superstrate (incidence side) to the substrate; light travels +z.\n  R is measured in the superstrate, T in the substrate.\n- mode: cross-section in the xy plane, propagation along +z.\n- device: ports are planes whose normal is the axis where size_nm is zero; direction is into the device.\n- problem.options[<method or backend name>] holds solver options, validated by that backend.\n- Materials: {\"kind\": \"constant_index\", \"n_real\": .., \"n_imag\": ..}, {\"kind\": \"library\", \"name\": \"Au\"},\n  drude, drude_lorentz, tabulated, constant_permittivity. FDTD needs dispersive models (fit_drude_lorentz).\n- Results carry provenance and warnings: read the warnings before trusting the numbers.\n",
  "backends": [
    {
      "name": "lightsmith-fde",
      "method": "fde",
      "available": true,
      "gpu": false,
      "auto_rank": 0
    }
  ],
  "example": {
    "kind": "mode",
    "structures": [
      {
        "profile": {
          "kind": "rectangle",
          "size_nm": [
            500,
            220
          ]
        },
        "material": {
          "kind": "constant_index",
          "n_real": 3.48
        }
      }
    ],
    "background": {
      "kind": "constant_index",
      "n_real": 1.44
    },
    "window_size_nm": [
      2500,
      1600
    ],
    "wavelengths": [
      1550
    ],
    "num_modes": 2,
    "options": {
      "fde": {
        "grid_spacing_nm": 40
      }
    }
  }
}

